    border-radius: 6px;
    font-size: 1rem;
}

.kanban-board {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 1rem;
    align-items: start;
}

.kanban-column {
    background: #f1f3f5;
    border-radius: 8px;
    padding: 1rem;
    min-height: 300px;
    display: flex;
    flex-direction: column;
}

.kanban-column-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.kanban-column-header h3 {
    margin: 0;
    font-size: 1rem;
}

.task-count {
    background: #dee2e6;
    border-radius: 12px;
    padding: 0.1rem 0.5rem;
    font-size: 0.8rem;
    font-weight: bold;
}

.kanban-column-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.kanban-column-footer {
    margin-top: 0.75rem;
}

.task-card {
    background: #ffffff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
}

.task-card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.4rem;
}

.task-title {
    font-weight: 600;
    font-size: 0.9rem;
}

.priority-badge {
    font-size: 0.7rem;
    padding: 0.15rem 0.5rem;
    border-radius: 10px;
    font-weight: bold;
    text-transform: uppercase;
}

.priority-high {
    background: #dc3545;
    color: #fff;
}

.priority-medium {
    background: #ffc107;
    color: #212529;
}

.priority-low {
    background: #28a745;
    color: #fff;
}

.task-card-body {
    display: flex;
    justify-content: space-between;
    font-size: 0.8rem;
    color: #6c757d;
    margin-bottom: 0.4rem;
}

.task-card-actions {
    display: flex;
    gap: 0.5rem;
}

.btn-move {
    font-size: 0.75rem;
    padding: 0.2rem 0.5rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    background: #fff;
    cursor: pointer;
}

.btn-move:hover {
    background: #e9ecef;
}

.btn-add-task {
    width: 100%;
    padding: 0.4rem;
    border: 1px dashed #adb5bd;
    border-radius: 6px;
    background: transparent;
    cursor: pointer;
    color: #6c757d;
}

.btn-add-task:hover {
    background: #e9ecef;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.add-task-form input,
.add-task-form select {
    padding: 0.4rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 0.85rem;
}

.add-task-form-actions {
    display: flex;
    gap: 0.5rem;
}

.btn-save {
    flex: 1;
    padding: 0.4rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-cancel {
    flex: 1;
    padding: 0.4rem;
    background: #6c757d;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.loading-message {
    text-align: center;
    color: #6c757d;
    padding: 2rem;
}

.error-message {
    text-align: center;
    color: #dc3545;
    padding: 1rem;
    background: #f8d7da;
    border-radius: 6px;
}

